async (page) => {
  const { execSync } = require('child_process');
  const fs = require('fs');

  try {
    // Get the status of all services
    // Using systemctl to list all services and their status
    const output = execSync('systemctl list-units --type=service --all --no-pager', { encoding: 'utf-8' });

    // Save to file
    fs.writeFileSync('/workspace/services_status.txt', output);

    return 'Services status saved successfully to /workspace/services_status.txt';
  } catch (error) {
    return `Error: ${error.message}`;
  }
}
